pub fn refresh_foot_lock(
    state: &mut AlsFootLockFootState,
    target_location: Vec3,
    target_rotation: Quat,
    ik_amount: f32,
    requested_lock_amount: f32,
    allow_foot_lock: bool,
    moving_smooth: bool,
    grounded: bool,
    became_valid: bool,
    delta_seconds: f32,
    current_base: Option<AlsFootLockMovementBase>,
) {
    state.target_location = target_location;
    state.target_rotation = target_rotation;

    if (became_valid || state.movement_base.map(|base| base.entity) != current_base.map(|base| base.entity))
        && is_relevant_animation_weight(ik_amount * state.lock_amount)
    {
        if became_valid {
            state.lock_location = target_location;
            state.lock_rotation = target_rotation;
        }
        capture_foot_lock_movement_base(state, current_base);
    }

    let mut new_lock_amount = requested_lock_amount.clamp(0.0, 1.0);
    if moving_smooth || !grounded {
        let decrease_speed = if moving_smooth {
            FOOT_LOCK_MOVING_DECREASE_PER_SECOND
        } else {
            FOOT_LOCK_NOT_GROUNDED_DECREASE_PER_SECOND
        };
        new_lock_amount = if became_valid {
            0.0
        } else {
            new_lock_amount
                .min((state.lock_amount - delta_seconds.max(0.0) * decrease_speed).max(0.0))
        };
    }

    if !allow_foot_lock
        || !is_relevant_animation_weight(ik_amount.clamp(0.0, 1.0) * new_lock_amount)
    {
        state.lock_amount = 0.0;
        state.lock_location = Vec3::ZERO;
        state.lock_rotation = Quat::IDENTITY;
        state.lock_rotation_before_foot_limit = Quat::IDENTITY;
        state.movement_base = None;
        state.lock_location_movement_base = Vec3::ZERO;
        state.lock_rotation_movement_base = Quat::IDENTITY;
        state.final_location = target_location;
        state.final_rotation = target_rotation;
        return;
    }

    let full_weight = is_full_animation_weight(new_lock_amount);
    let greater_than_previous = new_lock_amount > state.lock_amount;
    if full_weight {
        if greater_than_previous && (state.lock_amount <= 0.9 || current_base.is_some()) {
            let (location, rotation) = if became_valid {
                (target_location, target_rotation)
            } else {
                (state.final_location, state.final_rotation)
            };
            state.lock_location = location;
            state.lock_rotation = rotation;
        }
        state.lock_amount = 1.0;
        if greater_than_previous {
            capture_foot_lock_movement_base(state, current_base);
        }
    } else if !greater_than_previous {
        state.lock_amount = new_lock_amount;
    }

    advance_foot_lock_movement_base(state, current_base);
    state.lock_rotation_before_foot_limit = state.lock_rotation;
    state.final_location = target_location.lerp(state.lock_location, state.lock_amount);
    state.final_rotation = target_rotation
        .lerp(state.lock_rotation, state.lock_amount)
        .normalize();
}

fn refresh_previous_foot_lock_transform(
    state: &mut crate::als::foot_ik::AlsFootLockFootState,
    previous_character_transform: &Transform,
    current_character_transform: &Transform,
    rebase_lock: bool,
) {
    let previous_inverse = previous_character_transform.to_matrix().inverse();
    let current_matrix = current_character_transform.to_matrix();
    state.final_location =
        current_matrix.transform_point3(previous_inverse.transform_point3(state.final_location));
    let rotation_delta =
        current_character_transform.rotation * previous_character_transform.rotation.conjugate();
    state.final_rotation = (rotation_delta * state.final_rotation).normalize();
    if rebase_lock {
        state.lock_location =
            current_matrix.transform_point3(previous_inverse.transform_point3(state.lock_location));
        state.lock_rotation = (rotation_delta * state.lock_rotation_before_foot_limit).normalize();
    }
}

fn source_constrain_foot_lock(
    state: &mut AlsFootLockFootState,
    armature: &GlobalTransform,
    pelvis_world: &GlobalTransform,
    thigh_axis_pelvis_space: Vec3,
    settings: &AlsFootLockSettings,
) {
    if !is_relevant_animation_weight(state.lock_amount) {
        return;
    }
    let pelvis_rotation_armature =
        armature_rotation_from_world(armature, WorldRotation(pelvis_world.rotation())).0;
    let thigh_axis_armature = pelvis_rotation_armature * thigh_axis_pelvis_space;
    let mut lock_location_armature =
        armature_point_from_world(armature, WorldPoint(state.lock_location)).0;
    let mut lock_rotation_armature =
        armature_rotation_from_world(armature, WorldRotation(state.lock_rotation)).0;
    if let Some(offset_rotation) = foot_lock_location_constraint_rotation(
        thigh_axis_armature,
        lock_location_armature,
        settings.thigh_angle_limit_degrees,
    ) {
        lock_location_armature = offset_rotation * lock_location_armature;
        lock_rotation_armature = (offset_rotation * lock_rotation_armature).normalize();
        state.lock_location =
            world_point_from_armature(armature, ArmaturePoint(lock_location_armature)).0;
        state.lock_rotation =
            world_rotation_from_armature(armature, ArmatureRotation(lock_rotation_armature)).0;
        capture_foot_lock_movement_base(state, state.movement_base);
        state.lock_rotation_before_foot_limit = state.lock_rotation;
    }
    state.lock_rotation = constrain_foot_lock_rotation(
        state.lock_rotation,
        state.target_rotation,
        settings.foot_angle_limit_degrees,
    );
    state.final_location = state
        .target_location
        .lerp(state.lock_location, state.lock_amount);
    state.final_rotation = state
        .target_rotation
        .lerp(state.lock_rotation, state.lock_amount)

fn positive_scale_foot_rotation(
    target: Entity,
    avatar: Entity,
    armature: &GlobalTransform,
    parents: &Query<&ChildOf>,
    local_transforms: &Query<(&Transform, Option<&AnimationTargetId>)>,
    player: Option<&AnimationGraphPlayer>,
) -> Option<Quat> {
    let mut rotations = Vec::new();
    let mut current = target;
    while current != avatar {
        let (local, target_id) = local_transforms.get(current).ok()?;
        if local.scale.min_element() < 0.0 { return None; }
        let bone = player.zip(target_id).is_some_and(|(player, id)| {
            let id = (*id).into();
            player.get_default_output_pose().is_some_and(|pose| pose.paths.contains_key(&id))
                && player.bone_entity(id) == Some(current)
        });
        rotations.push((local.rotation.as_dquat(), bone));
        current = parents.get(current).ok()?.parent();
    }
    let mut ancestor = Some(avatar);
    while let Some(entity) = ancestor {
        if local_transforms.get(entity).ok()?.0.scale.min_element() < 0.0 { return None; }
        ancestor = parents.get(entity).ok().map(ChildOf::parent);
    }
    if rotations.is_empty() { return Some(armature.rotation()); }
    let mut prefix = bevy::math::DQuat::IDENTITY;
    let mut component_rotation = None;
    while let Some((rotation, bone)) = rotations.pop() {
        if let Some(component) = component_rotation {
            let combined = component * rotation;
            component_rotation = Some(if bone { rig_normalize(combined) } else { combined });
        } else if bone {
            component_rotation = Some(rotation);
        } else {
            prefix *= rotation;
        }
    }
    Some((armature.rotation().as_dquat() * prefix
        * component_rotation.unwrap_or(bevy::math::DQuat::IDENTITY)).as_quat())
}

