/**
 * Fast Linear Quaternion Interpolation.
 * Result is NOT normalized.
 */
template<typename T>
inline TQuat<T> TQuat<T>::FastLerp(const TQuat<T>& A, const TQuat<T>& B, const T Alpha)
{
	// To ensure the 'shortest route', we make sure the dot product between the both rotations is positive.
	const T DotResult = (A | B);
	const T Bias = FMath::FloatSelect(DotResult, T(1.0f), T(-1.0f));
	return (B * Alpha) + (A * (Bias * (1.f - Alpha)));
}

fn lerp_impl(self, end: Self, s: f64) -> Self {
    (self * (1.0 - s) + end * s).normalize()
}

/// Performs a linear interpolation between `self` and `rhs` based on
/// the value `s`.
///
/// When `s` is `0.0`, the result will be equal to `self`.  When `s`
/// is `1.0`, the result will be equal to `rhs`.
///
/// # Panics
///
/// Will panic if `self` or `end` are not normalized when `glam_assert` is enabled.
#[doc(alias = "mix")]
#[inline]
#[must_use]
pub fn lerp(self, end: Self, s: f64) -> Self {
    glam_assert!(self.is_normalized());
    glam_assert!(end.is_normalized());

    let dot = self.dot(end);
    let bias = if dot >= 0.0 { 1.0 } else { -1.0 };
    self.lerp_impl(end * bias, s)
}
